-- To‘liq sohalar va kasblar katalogi (40 soha). Mavjud sohalar slug bo‘yicha yangilanadi, yangilari qo‘shiladi; mavjud bo‘limlar va vakansiyalar o‘zgarmaydi
ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "short" = EXCLUDED."short", "sort" = EXCLUDED."sort", "active" = true, "updatedAt" = CURRENT_TIMESTAMP;

-- Katalogga kirmagan eski sohalar ro‘yxat oxiriga o‘tadi — eski vakansiyalar uchun saqlanadi
UPDATE "Category" SET "sort" = 1000 + "sort" WHERE "parentId" IS NULL AND "slug" IN ('housekeeper', 'cleaning', 'cook', 'caregiver');

-- Kasblar (bo‘limlar): slug = <soha>-<kasb>, chunki slug butun jadvalda yagona
ON CONFLICT ("slug") DO NOTHING;
